import java.util.List;

public class CovarianceDemo {
    // Base domain model
    static class SensorReading {
        final double value;
        SensorReading(double value) { this.value = value; }
        public double getValue() { return value; }
    }

    static class TemperatureReading extends SensorReading {
        TemperatureReading(double val) { super(val); }
    }

    static class PressureReading extends SensorReading {
        PressureReading(double val) { super(val); }
    }

    // Covariant method: accepts List of SensorReading OR ANY of its subclasses!
    public static double computeAverage(List<? extends SensorReading> readings) {
        if (readings == null || readings.isEmpty()) return 0.0;
        double sum = 0.0;
        for (SensorReading r : readings) {
            // Safe reading guaranteed by upper bound!
            sum += r.getValue();
        }
        return sum / readings.size();
    }

    public static void main(String[] args) {
        List<TemperatureReading> temps = List.of(
            new TemperatureReading(21.5),
            new TemperatureReading(22.0),
            new TemperatureReading(20.5)
        );

        List<PressureReading> pressures = List.of(
            new PressureReading(1013.25),
            new PressureReading(1014.10)
        );

        // Both specific sub-type lists are passed directly to computeAverage:
        System.out.printf("Avg Temp:     %.2f°C%n", computeAverage(temps));
        System.out.printf("Avg Pressure: %.2f hPa%n", computeAverage(pressures));
    }
}
// Expected Output:
// Avg Temp:     21.33°C
// Avg Pressure: 1013.68 hPa

