import java.util.List;

public class NumberAggregator {
    public static double calculateSum(List<? extends Number> numbers) {
        double total = 0.0;
        for (Number num : numbers) {
            if (num != null) {
                total += num.doubleValue();
            }
        }
        return total;
    }

    public static void main(String[] args) {
        List<Integer> intList = List.of(10, 20, 30);
        List<Double> dblList = List.of(1.5, 2.5, 3.5);

        System.out.println("Integer sum: " + calculateSum(intList)); // 60.0
        System.out.println("Double sum:  " + calculateSum(dblList)); // 7.5
    }
}

