import java.util.List;

public class MaxNumberFinder {
    public static double findMaxAsDouble(List<? extends Number> numbers) {
        return Double.NaN;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(10, 50, 20);
        List<Double> doubles = List.of(1.5, 9.9, 4.2);
        System.out.println(findMaxAsDouble(ints));    // 50.0
        System.out.println(findMaxAsDouble(doubles)); // 9.9
    }
}

practiceProblems.solutionCode:
import java.util.List;

public class MaxNumberFinder {
    public static double findMaxAsDouble(List<? extends Number> numbers) {
        if (numbers == null || numbers.isEmpty()) return Double.NaN;
        double max = Double.NEGATIVE_INFINITY;
        for (Number num : numbers) {
            if (num != null && num.doubleValue() > max) {
                max = num.doubleValue();
            }
        }
        return max == Double.NEGATIVE_INFINITY ? Double.NaN : max;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(10, 50, 20);
        List<Double> doubles = List.of(1.5, 9.9, 4.2);
        System.out.println(findMaxAsDouble(ints));
        System.out.println(findMaxAsDouble(doubles));
    }
}

