import java.util.List;

public class ThresholdCounter {
    public static int countExceeding(List<? extends Number> numbers, double threshold) {
        if (numbers == null) return 0;
        int count = 0;
        for (Number num : numbers) {
            if (num != null && num.doubleValue() > threshold) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(5, 12, 18, 3, 25);
        System.out.println(countExceeding(ints, 10.0));
    }
}

