import java.util.List;

public class EvenNumberSum {
    public static long sumEvenInts(List<? extends Number> numbers) {
        if (numbers == null) return 0L;
        long sum = 0L;
        for (Number num : numbers) {
            if (num != null) {
                int val = num.intValue();
                if (val % 2 == 0) {
                    sum += val;
                }
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(1, 2, 3, 4, 5, 6);
        System.out.println(sumEvenInts(ints));
    }
}

