practiceProblems.solutionCode:
import java.util.List;

public class PositiveChecker {
    public static boolean areAllPositive(List<? extends Number> numbers) {
        if (numbers == null) return true;
        for (Number num : numbers) {
            if (num != null && num.doubleValue() <= 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(areAllPositive(List.of(1, 2.5, 30L)));
        System.out.println(areAllPositive(List.of(1, -2.5, 30L)));
    }
}

