import java.util.List;

public class PrefixMatcher {
    public static CharSequence findWithPrefix(List<? extends CharSequence> list, String prefix) {
        if (list == null || prefix == null) return null;
        for (CharSequence cs : list) {
            if (cs != null && cs.toString().startsWith(prefix)) {
                return cs;
            }
        }
        return null;
    }

    public static void main(String[] args) {
        List<String> words = List.of("apple", "banana", "apricot");
        System.out.println(findWithPrefix(words, "ap"));
    }
}
